1	// Copyright 2026 erash11 and contributors. Licensed under Apache-2.0. See LICENSE.
2	// Shared helpers for the hand-written novel commands (acwr, pb, benchmark,
3	// rtp, diff, heatmap, report). Live-API strategy: these commands fetch stats
4	// through the generated client and compute locally; the stats engine cannot
5	// express rolling windows, ranks, or cross-session joins.
6	package cli
7	
8	import (
9		"context"
10		"encoding/json"
11		"fmt"
12		"sort"
13		"strconv"
14		"strings"
15		"time"
16	
17		"catapult-openfield-connect-pp-cli/internal/client"
18		"catapult-openfield-connect-pp-cli/internal/cliutil"
19	)
20	
21	type statsRow map[string]json.RawMessage
22	
23	func rowString(r statsRow, key string) string {
24		raw, ok := r[key]
25		if !ok {
26			return ""
27		}
28		var s string
29		if err := json.Unmarshal(raw, &s); err == nil {
30			return s
31		}
32		var n float64
33		if err := json.Unmarshal(raw, &n); err == nil {
34			return strconv.FormatFloat(n, 'f', -1, 64)
35		}
36		return strings.Trim(string(raw), `"`)
37	}
38	
39	func rowNum(r statsRow, key string) (float64, bool) {
40		return cliutil.ExtractNumber(map[string]json.RawMessage(r), key)
41	}
42	
43	func statsFilter(name, comparison string, values ...string) map[string]any {
44		return map[string]any{"name": name, "comparison": comparison, "values": values}
45	}
46	
47	// fetchStatsRows POSTs /stats with the given parameter slugs, grouping, and
48	// filters, returning tolerant map rows (metric values may arrive as numbers
49	// or JSON-encoded strings).
50	func fetchStatsRows(ctx context.Context, c *client.Client, parameters, groupBy []string, filters []map[string]any) ([]statsRow, error) {
51		body := map[string]any{
52			"parameters": parameters,
53			"group_by":   groupBy,
54		}
55		if len(filters) > 0 {
56			body["filters"] = filters
57		}
58		data, _, err := c.PostQueryWithParams(ctx, "/stats", map[string]string{"requested_only": "false"}, body)
59		if err != nil {
60			return nil, err
61		}
62		rows := make([]statsRow, 0)
63		if err := json.Unmarshal(data, &rows); err != nil {
64			// Some tenants wrap the array in an envelope; try common shapes.
65			var envelope map[string]json.RawMessage
66			if envErr := json.Unmarshal(data, &envelope); envErr == nil {
67				for _, key := range []string{"data", "results", "stats"} {
68					if inner, ok := envelope[key]; ok {
69						if err2 := json.Unmarshal(inner, &rows); err2 == nil {
70							return rows, nil
71						}
72					}
73				}
74			}
75			return nil, fmt.Errorf("parsing stats response: %w", err)
76		}
77		return rows, nil
78	}
79	
80	type activityMeta struct {
81		ID    string
82		Name  string
83		Start time.Time
84	}
85	
86	// fetchActivityIndex lists activities in [from, to] and returns them keyed by
87	// ID, plus a slice sorted by start time ascending.
88	func fetchActivityIndex(ctx context.Context, c *client.Client, from, to time.Time) (map[string]activityMeta, []activityMeta, error) {
89		params := map[string]string{}
90		if !from.IsZero() {
91			params["startTime"] = strconv.FormatInt(from.Unix(), 10)
92		}
93		if !to.IsZero() {
94			params["endTime"] = strconv.FormatInt(to.Unix(), 10)
95		}
96		data, err := c.Get(ctx, "/activities", params)
97		if err != nil {
98			return nil, nil, err
99		}
100		var raw []statsRow
101		if err := json.Unmarshal(data, &raw); err != nil {
102			return nil, nil, fmt.Errorf("parsing activities response: %w", err)
103		}
104		index := make(map[string]activityMeta, len(raw))
105		ordered := make([]activityMeta, 0, len(raw))
106		for _, r := range raw {
107			id := rowString(r, "id")
108			if id == "" {
109				continue
110			}
111			meta := activityMeta{ID: id, Name: rowString(r, "name")}
112			if ts, ok := cliutil.ExtractNumber(map[string]json.RawMessage(r), "start_time"); ok && ts > 0 {
113				meta.Start = time.Unix(int64(ts), 0)
114			}
115			index[id] = meta
116			ordered = append(ordered, meta)
117		}
118		sort.Slice(ordered, func(i, j int) bool { return ordered[i].Start.Before(ordered[j].Start) })
119		return index, ordered, nil
120	}
121	
122	type athleteMeta struct {
123		ID       string
124		Name     string
125		Position string
126	}
127	
128	func fetchAthleteIndex(ctx context.Context, c *client.Client) (map[string]athleteMeta, error) {
129		data, err := c.Get(ctx, "/athletes", nil)
130		if err != nil {
131			return nil, err
132		}
133		var raw []statsRow
134		if err := json.Unmarshal(data, &raw); err != nil {
135			return nil, fmt.Errorf("parsing athletes response: %w", err)
136		}
137		out := make(map[string]athleteMeta, len(raw))
138		for _, r := range raw {
139			id := rowString(r, "id")
140			if id == "" {
141				continue
142			}
143			name := strings.TrimSpace(rowString(r, "first_name") + " " + rowString(r, "last_name"))
144			pos := rowString(r, "position_name")
145			if pos == "" {
146				pos = rowString(r, "position")
147			}
148			out[id] = athleteMeta{ID: id, Name: name, Position: pos}
149		}
150		return out, nil
151	}
152	
153	// matchAthlete resolves a case-insensitive full/partial name to one athlete.
154	func matchAthlete(index map[string]athleteMeta, query string) (athleteMeta, error) {
155		q := strings.ToLower(strings.TrimSpace(query))
156		var hits []athleteMeta
157		for _, a := range index {
158			if strings.Contains(strings.ToLower(a.Name), q) {
159				hits = append(hits, a)
160			}
161		}
162		switch len(hits) {
163		case 1:
164			return hits[0], nil
165		case 0:
166			return athleteMeta{}, notFoundErr(fmt.Errorf("no athlete matching %q", query))
167		default:
168			names := make([]string, 0, len(hits))
169			for _, h := range hits {
170				names = append(names, h.Name)
171			}
172			sort.Strings(names)
173			return athleteMeta{}, usageErr(fmt.Errorf("athlete %q is ambiguous: %s", query, strings.Join(names, ", ")))
174		}
175	}
176	
177	// riskZone buckets an acute:chronic ratio using the standard thresholds.
178	func riskZone(acwr float64) string {
179		switch {
180		case acwr <= 0:
181			return "no-data"
182		case acwr < 0.8:
183			return "caution-low"
184		case acwr <= 1.3:
185			return "safe"
186		case acwr <= 1.5:
187			return "caution"
188		default:
189			return "danger"
190		}
191	}
192	
193	func dayKey(t time.Time) string { return t.Format("2006-01-02") }
194	
195	// resolveActivityArg turns an activity reference (raw ID, YYYY-MM-DD or
196	// YYYYMMDD date, "last", "prev") into an activity from the ordered index.
197	func resolveActivityArg(arg string, index map[string]activityMeta, ordered []activityMeta) (activityMeta, error) {
198		if m, ok := index[arg]; ok {
199			return m, nil
200		}
201		if len(ordered) > 0 {
202			switch strings.ToLower(arg) {
203			case "last", "latest":
204				return ordered[len(ordered)-1], nil
205			case "prev", "previous":
206				if len(ordered) > 1 {
207					return ordered[len(ordered)-2], nil
208				}
209			}
210		}
211		norm := arg
212		if len(arg) == 8 {
213			if _, err := strconv.Atoi(arg); err == nil {
214				norm = arg[0:4] + "-" + arg[4:6] + "-" + arg[6:8]
215			}
216		}
217		if _, err := time.Parse("2006-01-02", norm); err == nil {
218			var candidates []activityMeta
219			for _, m := range ordered {
220				if !m.Start.IsZero() && dayKey(m.Start) == norm {
221					candidates = append(candidates, m)
222				}
223			}
224			if len(candidates) > 0 {
225				return candidates[len(candidates)-1], nil
226			}
227			return activityMeta{}, notFoundErr(fmt.Errorf("no activity on %s", norm))
228		}
229		return activityMeta{}, notFoundErr(fmt.Errorf("activity %q not found (pass an ID, a date like 2026-03-15, 'last', or 'prev')", arg))
230	}
231	
232	func median(vals []float64) float64 {
233		if len(vals) == 0 {
234			return 0
235		}
236		s := append([]float64(nil), vals...)
237		sort.Float64s(s)
238		mid := len(s) / 2
239		if len(s)%2 == 0 {
240			return (s[mid-1] + s[mid]) / 2
241		}
242		return s[mid]
243	}
244	
245	func round2(v float64) float64 { return float64(int(v*100+0.5)) / 100 }
246	
247	func max(a, b int) int {
248		if a > b {
249			return a
250		}
251		return b
252	}
253	
254	// sortAcwr orders rows danger-first, then by ratio descending.
255	func sortAcwr(rows []acwrRow) {
256		zoneRank := map[string]int{"danger": 0, "caution": 1, "caution-low": 2, "safe": 3, "no-data": 4}
257		sort.Slice(rows, func(i, j int) bool {
258			if zoneRank[rows[i].RiskZone] != zoneRank[rows[j].RiskZone] {
259				return zoneRank[rows[i].RiskZone] < zoneRank[rows[j].RiskZone]
260			}
261			return rows[i].ACWR > rows[j].ACWR
262		})
263	}
264	
265	// rowDate returns the row's session date (YYYY-MM-DD), preferring the stats
266	// engine's own date column, falling back to start_time.
267	func rowDate(r statsRow) string {
268		if d := rowString(r, "date"); d != "" {
269			if norm := normalizeDay(d); norm != "" {
270				return norm
271			}
272		}
273		if ts, ok := cliutil.ExtractNumber(map[string]json.RawMessage(r), "start_time"); ok && ts > 0 {
274			return dayKey(time.Unix(int64(ts), 0))
275		}
276		return ""
277	}
278	
279	// normalizeDay accepts the formats OpenField actually emits (MM/DD/YYYY on
280	// US tenants, ISO elsewhere) and returns YYYY-MM-DD, or "" when unparseable.
281	func normalizeDay(d string) string {
282		if len(d) > 10 {
283			d = d[:10]
284		}
285		for _, layout := range []string{"2006-01-02", "01/02/2006", "1/2/2006"} {
286			if t, err := time.Parse(layout, d); err == nil {
287				return dayKey(t)
288			}
289		}
290		return ""
291	}
292	
293	// indexFromRows derives an activity index from stats rows themselves
294	// (requested_only=false rows carry activity_id/activity_name/start_time).
295	func indexFromRows(rows []statsRow) map[string]activityMeta {
296		out := map[string]activityMeta{}
297		for _, r := range rows {
298			id := rowString(r, "activity_id")
299			if id == "" {
300				continue
301			}
302			if _, ok := out[id]; ok {
303				continue
304			}
305			meta := activityMeta{ID: id, Name: rowString(r, "activity_name")}
306			if ts, ok := cliutil.ExtractNumber(map[string]json.RawMessage(r), "start_time"); ok && ts > 0 {
307				meta.Start = time.Unix(int64(ts), 0)
308			}
309			out[id] = meta
310		}
311		return out
312	}
313	
314	// fetchStatsWindow fetches per-athlete-per-activity stats rows for [from, to].
315	// The OpenField date filter hangs server-side (observed 2026-08-06), so the
316	// window is expressed as an activity_id set from the fast /activities listing.
317	// Under verify/dogfood envs it curtails to the last 8 activities to fit the
318	// probe time budget.
319	func fetchStatsWindow(ctx context.Context, c *client.Client, parameters []string, from, to time.Time) ([]statsRow, error) {
320		if cliutil.IsVerifyEnv() || cliutil.IsDogfoodEnv() {
321			rows, err := fetchStatsRows(ctx, c, parameters, []string{"athlete", "activity"},
322				[]map[string]any{statsFilter("lastActivities", "=", "8")})
323			if err != nil {
324				return nil, err
325			}
326			fromKey, toKey := dayKey(from), dayKey(to)
327			kept := rows[:0]
328			for _, r := range rows {
329				if d := rowDate(r); d >= fromKey && d <= toKey {
330					kept = append(kept, r)
331				}
332			}
333			return kept, nil
334		}
335		_, ordered, err := fetchActivityIndex(ctx, c, from, to)
336		if err != nil {
337			return nil, err
338		}
339		if len(ordered) == 0 {
340			return nil, nil
341		}
342		ids := make([]string, 0, len(ordered))
343		for _, m := range ordered {
344			ids = append(ids, m.ID)
345		}
346		return fetchStatsRows(ctx, c, parameters, []string{"athlete", "activity"},
347			[]map[string]any{statsFilter("activity_id", "=", ids...)})
348	}
349	
350	// fetchPB returns each athlete's aggregated value for a metric (max for
351	// velocity-style metrics) over the last N activities. A true all-time query
352	// (no filter) exceeds 90s server-side on real tenants; N=60 answers in ~6s
353	// and covers a season. Curtailed to 8 under verify/dogfood envs.
354	func fetchPB(ctx context.Context, c *client.Client, metric string, lastN int) (map[string]float64, error) {
355		if cliutil.IsVerifyEnv() || cliutil.IsDogfoodEnv() {
356			lastN = 8
357		}
358		rows, err := fetchStatsRows(ctx, c, []string{metric}, []string{"athlete"},
359			[]map[string]any{statsFilter("lastActivities", "=", fmt.Sprint(lastN))})
360		if err != nil {
361			return nil, err
362		}
363		out := make(map[string]float64, len(rows))
364		for _, r := range rows {
365			if v, ok := rowNum(r, metric); ok {
366				out[rowString(r, "athlete_id")] = v
367			}
368		}
369		return out, nil
370	}
371

