54				defer cancel()
55				c, err := flags.newClient()
56				if err != nil {
57					return err
58				}
59				pbByAthlete, err := fetchPB(ctx, c, flagMetric, flagPBWindow)
60				if err != nil {
61					return classifyAPIError(err, flags)
62				}
63				recent, err := fetchStatsRows(ctx, c, []string{flagMetric}, []string{"athlete", "activity"},
64					[]map[string]any{statsFilter("lastActivities", "=", fmt.Sprint(flagRecent))})
65				if err != nil {
