45	Tracks an injured athlete's per-session load as a percentage of the squad
46	average for the same session, or of the athlete's own pre-injury baseline
47	window (--baseline 2026-01-01..2026-02-15).
48	
49	Use this command for one athlete's rehab progression vs squad or baseline.
50	Do NOT use it for squad-wide risk screening; use 'acwr'.`),
51			Example:     "  catapult-openfield-connect-pp-cli rtp --athlete \"M. Lee\" --target-metric total_player_load --vs-squad --threshold 85 --agent",
52			Annotations: map[string]string{"mcp:read-only": "true"},
53			RunE: func(cmd *cobra.Command, args []string) error {
54				if len(args) == 0 && cmd.Flags().NFlag() == 0 {
55					return cmd.Help()
56				}
57				if dryRunOK(flags) {
58					return writeDryRun(cmd.OutOrStdout(), flags, "rtp")
59				}
60				if flagAthlete == "" {
61					_ = cmd.Usage()
62					return usageErr(fmt.Errorf("--athlete is required"))
63				}
64				if err := validateDataSourceStrategy(flags, "live"); err != nil {
65					return err
66				}
67				ctx, cancel := boundCtx(cmd.Context(), flags)
68				defer cancel()
69				c, err := flags.newClient()
70				if err != nil {
71					return err
72				}
73				now := time.Now()
74				start := now.AddDate(0, 0, -flagDays+1)
75				rows, err := fetchStatsWindow(ctx, c, []string{flagTargetMetric}, start, now)
76				if err != nil {
