81				if strings.EqualFold(flagAthlete, "top") {
82					// "top" = the athlete with the highest total load in the window
83					totals := map[string]float64{}
84					names := map[string]string{}
85					for _, r := range rows {
86						if v, ok := rowNum(r, flagTargetMetric); ok {
87							aid := rowString(r, "athlete_id")
88							totals[aid] += v
89							names[aid] = rowString(r, "athlete_name")
90						}
91					}
92					for aid, v := range totals {
93						if v > totals[target.ID] || target.ID == "" {
94							target = athleteMeta{ID: aid, Name: names[aid]}
95						}
96					}
97					if target.ID == "" {
98						return notFoundErr(fmt.Errorf("no athletes with data in the last %d days", flagDays))
99					}
100				} else {
101					athletes, err := fetchAthleteIndex(ctx, c)
102					if err != nil {
103						return classifyAPIError(err, flags)
104					}
105					target, err = matchAthlete(athletes, flagAthlete)
106					if err != nil {
107						return err
108					}
109				}
110				// reference: baseline avg, or per-activity squad average
111				reference := "squad-average"
