118					}
119					bFrom, errF := time.Parse("2006-01-02", parts[0])
120					bTo, errT := time.Parse("2006-01-02", parts[1])
121					if errF != nil || errT != nil {
122						_ = cmd.Usage()
123						return usageErr(fmt.Errorf("--baseline dates must be YYYY-MM-DD"))
124					}
125					bRows, err := fetchStatsWindow(ctx, c, []string{flagTargetMetric}, bFrom, bTo)
126					if err != nil {
127						return classifyAPIError(err, flags)
128					}
129					var total float64
130					var n int
131					for _, r := range bRows {
132						if rowString(r, "athlete_id") != target.ID {
