34	}
35	
36	func newNovelDiffCmd(flags *rootFlags) *cobra.Command {
37		var flagSquad bool
38		var flagMetrics string
39		var flagAthlete string
40	
41		cmd := &cobra.Command{
42			Use:   "diff <activity-a> <activity-b>",
43			Short: "Side-by-side comparison of two sessions: absolute and % change per metric per athlete",
44			Long: strings.TrimSpace(`
45	Compares two activities (by ID, date like 2026-03-15 or 20260315, or the
46	keywords 'last'/'prev') and prints per-athlete, per-metric deltas.
47	
48	Use this command to compare TWO sessions.
49	Do NOT use it for period-by-period breakdown within one session; use 'heatmap'.`),
50			Example:     "  catapult-openfield-connect-pp-cli diff last prev --squad --metrics total_player_load,max_vel --agent",
51			Annotations: map[string]string{"mcp:read-only": "true", "pp:happy-args": "activity-a=last;activity-b=prev"},
52			RunE: func(cmd *cobra.Command, args []string) error {
53				if len(args) == 0 && cmd.Flags().NFlag() == 0 {
54					return cmd.Help()
55				}
56				if len(args) < 2 {
57					_ = cmd.Usage()
58					return usageErr(fmt.Errorf("two activity references are required (ID, date, 'last', or 'prev')"))
59				}
60				if dryRunOK(flags) {
61					return writeDryRun(cmd.OutOrStdout(), flags, "diff")
62				}
63				if err := validateDataSourceStrategy(flags, "live"); err != nil {
64					return err
65				}
66				ctx, cancel := boundCtx(cmd.Context(), flags)
67				defer cancel()
68				metrics, err := cliutil.ParseStringList(flagMetrics)
69				if err != nil || len(metrics) == 0 {
70					_ = cmd.Usage()
71					return usageErr(fmt.Errorf("invalid --metrics list"))
72				}
73				c, err := flags.newClient()
74				if err != nil {
75					return err
76				}
77				now := time.Now()
78				actIndex, ordered, err := fetchActivityIndex(ctx, c, now.AddDate(-1, 0, 0), now)
79				if err != nil {
80					return classifyAPIError(err, flags)
81				}
82				actA, err := resolveActivityArg(args[0], actIndex, ordered)
83				if err != nil {
84					return err
85				}
86				actB, err := resolveActivityArg(args[1], actIndex, ordered)
87				if err != nil {
88					return err
89				}
90				if actA.ID == actB.ID {
91					return usageErr(fmt.Errorf("both references resolve to the same activity (%s)", actA.Name))
92				}
93				rows, err := fetchStatsRows(ctx, c, metrics, []string{"athlete", "activity"},
94					[]map[string]any{statsFilter("activity_id", "=", actA.ID, actB.ID)})
95				if err != nil {
96					return classifyAPIError(err, flags)
97				}
98				type pair struct {
99					name string
100					a, b map[string]float64
101				}
102				perAthlete := map[string]*pair{}
103				for _, r := range rows {
104					aid := rowString(r, "athlete_id")
105					if aid == "" {
106						continue
107					}
108					p := perAthlete[aid]
109					if p == nil {
110						p = &pair{name: rowString(r, "athlete_name"), a: map[string]float64{}, b: map[string]float64{}}
111						perAthlete[aid] = p
112					}
113					target := p.a
114					if rowString(r, "activity_id") == actB.ID {
115						target = p.b
116					}
117					for _, m := range metrics {
118						if v, ok := rowNum(r, m); ok {
119							target[m] += v
120						}
121					}
122				}
123				results := make([]diffRow, 0)
124				for aid, p := range perAthlete {
125					if flagAthlete != "" && !strings.Contains(strings.ToLower(p.name), strings.ToLower(flagAthlete)) {
126						continue
127					}
128					for _, m := range metrics {
129						va, vb := p.a[m], p.b[m]
130						if va == 0 && vb == 0 {
131							continue
132						}
133						pct := 0.0
134						if va != 0 {
135							pct = (vb - va) / va * 100
136						}
137						results = append(results, diffRow{
138							AthleteID: aid, AthleteName: p.name, Metric: m,
139							ValueA: round2(va), ValueB: round2(vb),
140							Delta: round2(vb - va), DeltaPct: round2(pct),
141						})
142					}
143				}
144				sort.Slice(results, func(i, j int) bool {
145					if results[i].AthleteName != results[j].AthleteName {
146						return results[i].AthleteName < results[j].AthleteName
147					}
148					return results[i].Metric < results[j].Metric
149				})
150				view := diffView{
151					RefA: args[0], RefB: args[1],
152					ActivityA: actA.Name, ActivityB: actB.Name,
153					DateA: dayKey(actA.Start), DateB: dayKey(actB.Start),
154					Rows: results,
155				}
156				if !wantsHumanTable(cmd.OutOrStdout(), flags) {
157					return printJSONFiltered(cmd.OutOrStdout(), view, flags)
158				}
159				if len(results) == 0 {
160					fmt.Fprintf(cmd.OutOrStdout(), "No overlapping stats between %s and %s for metrics %s.\n", actA.Name, actB.Name, flagMetrics)
161					return nil
162				}
163				fmt.Fprintf(cmd.OutOrStdout(), "A: %s (%s)   B: %s (%s)\n\n", actA.Name, dayKey(actA.Start), actB.Name, dayKey(actB.Start))
164				fmt.Fprintf(cmd.OutOrStdout(), "%-24s %-24s %10s %10s %9s\n", "ATHLETE", "METRIC", "A", "B", "Δ%%")
165				for _, r := range results {
166					fmt.Fprintf(cmd.OutOrStdout(), "%-24s %-24s %10.1f %10.1f %8.1f%%\n", r.AthleteName, r.Metric, r.ValueA, r.ValueB, r.DeltaPct)
167				}
168				return nil
169			},
170		}
171		cmd.Flags().BoolVar(&flagSquad, "squad", false, "Show the full squad (default)")
172		cmd.Flags().StringVar(&flagMetrics, "metrics", "total_player_load", "Comma-separated metric slugs to compare")
173		cmd.Flags().StringVar(&flagAthlete, "athlete", "", "Filter to athletes whose name contains this text")
174		return cmd
175	}
