15	)
16	
17	type reportRow struct {
18		AthleteName string  `json:"athlete_name"`
19		TotalLoad   float64 `json:"total_load"`
20		Sessions    int     `json:"sessions"`
21		ACWR        float64 `json:"acwr"`
22		RiskZone    string  `json:"risk_zone"`
23		MaxVel      float64 `json:"max_vel"`
24		MaxVelPBPct float64 `json:"max_vel_pb_pct"`
25		Monotony    float64 `json:"monotony"`
26		Strain      float64 `json:"strain"`
27	}
28	
29	func newNovelReportCmd(flags *rootFlags) *cobra.Command {
30		var flagWeek bool
31		var flagRange string
32		var flagSquad bool
33		var flagFormat string
34		var flagExport string
35	
36		cmd := &cobra.Command{
37			Use:   "report",
38			Short: "Weekly load summary: total load, sessions, ACWR, max vel vs PB, monotony, strain, risk flags",
39			Long: strings.TrimSpace(`
40	Generates the coach-briefing load summary for a window (--week = last 7 days,
41	or --range <from>..<to>): total Player Load, session count, ACWR, max velocity
42	vs personal best, Foster's monotony and strain, and risk flags. Exports as
43	markdown or CSV.
44	
45	Use this command for the multi-metric weekly export.
46	Do NOT use it for a live morning risk check; use 'acwr'.`),
47			Example:     "  catapult-openfield-connect-pp-cli report --week --squad --format markdown --export ./week_load.md",
48			Annotations: map[string]string{"mcp:read-only": "true"},
49			RunE: func(cmd *cobra.Command, args []string) error {
50				if len(args) == 0 && cmd.Flags().NFlag() == 0 {
51					return cmd.Help()
52				}
53				if dryRunOK(flags) {
54					return writeDryRun(cmd.OutOrStdout(), flags, "report")
55				}
56				if err := validateDataSourceStrategy(flags, "live"); err != nil {
57					return err
58				}
59				if flagFormat != "markdown" && flagFormat != "csv" {
60					_ = cmd.Usage()
61					return usageErr(fmt.Errorf("--format must be markdown or csv"))
62				}
63				ctx, cancel := boundCtx(cmd.Context(), flags)
64				defer cancel()
65				c, err := flags.newClient()
66				if err != nil {
67					return err
68				}
69				now := time.Now()
70				to := now
71				from := now.AddDate(0, 0, -6)
72				if flagRange != "" {
73					parts := strings.SplitN(flagRange, "..", 2)
74					if len(parts) != 2 {
75						_ = cmd.Usage()
76						return usageErr(fmt.Errorf("--range must be <from>..<to>, e.g. 2026-03-09..2026-03-15"))
77					}
78					f, errF := time.Parse("2006-01-02", parts[0])
79					t, errT := time.Parse("2006-01-02", parts[1])
80					if errF != nil || errT != nil {
81						_ = cmd.Usage()
82						return usageErr(fmt.Errorf("--range dates must be YYYY-MM-DD"))
83					}
84					from, to = f, t
85				}
86				// One 28-day fetch ending at `to` covers the report window,
87				// the ACWR chronic window, and daily-load monotony.
88				chronicStart := to.AddDate(0, 0, -27)
89				// The window and PB queries are independent; run them in
90				// parallel so the command fits interactive/probe time budgets.
91				var rows []statsRow
92				var pbByAthlete map[string]float64
93				var rowsErr, pbErr error
94				var wg sync.WaitGroup
95				wg.Add(2)
96				go func() {
97					defer wg.Done()
98					rows, rowsErr = fetchStatsWindow(ctx, c, []string{"total_player_load", "max_vel"}, chronicStart, to)
99				}()
100				go func() {
101					defer wg.Done()
102					pbByAthlete, pbErr = fetchPB(ctx, c, "max_vel", 60)
103				}()
104				wg.Wait()
105				if rowsErr != nil {
106					return classifyAPIError(rowsErr, flags)
107				}
108				if pbErr != nil {
109					return classifyAPIError(pbErr, flags)
110				}
111				type acc struct {
112					name       string
113					loadByDay  map[string]float64
114					weekLoad   float64
115					weekSess   int
116					weekMaxVel float64
117				}
118				perAthlete := map[string]*acc{}
119				fromKey, toKey := dayKey(from), dayKey(to)
120				acuteStart := dayKey(to.AddDate(0, 0, -6))
121				for _, r := range rows {
122					aid := rowString(r, "athlete_id")
123					if aid == "" {
124						continue
125					}
126					day := rowDate(r)
127					if day == "" {
128						continue
129					}
130					a := perAthlete[aid]
131					if a == nil {
132						a = &acc{name: rowString(r, "athlete_name"), loadByDay: map[string]float64{}}
133						perAthlete[aid] = a
134					}
135					load, hasLoad := rowNum(r, "total_player_load")
136					if hasLoad {
137						a.loadByDay[day] += load
138					}
139					if day >= fromKey && day <= toKey {
140						if hasLoad {
141							a.weekLoad += load
142						}
143						a.weekSess++
144						if v, ok := rowNum(r, "max_vel"); ok && v > a.weekMaxVel {
145							a.weekMaxVel = v
146						}
147					}
148				}
149				results := make([]reportRow, 0, len(perAthlete))
150				for aid, a := range perAthlete {
151					if a.weekSess == 0 {
152						continue
153					}
154					// ACWR from the 28d daily buckets
155					var acute, total float64
156					for day, v := range a.loadByDay {
157						total += v
158						if day >= acuteStart {
159							acute += v
160						}
161					}
162					chronicWeekly := total / 4
163					ratio := 0.0
